  "verses": [
    {
      "chapter": 5,
      "text_ar": "ثم قالت في نفسها: \"ما هو شعر رأسي مقارنة بزوجي الجائع؟\"",
      "verse": 21
    },
    {
      "chapter": 5,
      "text_ar": "ولما تأملت في الأمر قالت له: \"قم واحلق شعري\".",
      "verse": 22
    },
    {
      "chapter": 5,
      "text_ar": "ثم أخذ مقصاً وأزال شعر رأسمها بحضور الجميع، وأعطاها ثلاثة أرغفة من الخبز.",
      "verse": 23
    },
    {
      "chapter": 5,
      "text_ar": "ثم أخذتها وأحضرتها إليّ. وسار الشيطان خلفها في الطريق، مختبئاً وهو يمشي ومزعجاً قلبها جداً.",
      "verse": 24
    }
  ],
  "book_code": "TJOB"
}
